int[] zbudowane = {0};
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) { final int idx=i; t[i] = new Thread(() -> {
    if (instance == null) {
        try { Thread.sleep(5); } catch (Exception e) {}
        synchronized (zbudowane) { zbudowane[0]++; }
        instance = new ExpensiveObject(idx);
    }
}); }
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);
