boolean testAtomicity(Runnable operation, int threadCount, int opsPerThread, LongSupplier currentValue, long expected) throws InterruptedException {
    Thread[] t = new Thread[threadCount];
    for (int i=0;i<threadCount;i++) t[i] = new Thread(() -> { for (int j=0;j<opsPerThread;j++) operation.run(); });
    for (Thread th : t) th.start();
    for (Thread th : t) th.join(10_000);
    return currentValue.getAsLong() == expected;
}
System.out.println(testAtomicity(() -> count++, 4, 25_000, () -> count, 100_000) ? "PASS" : "FAIL");

